import { BaseHandler } from "../../response/base.js";
import { handleModuleServer } from "./module-server-handler.js";
import { handlePageModule } from "./page-module-handler.js";
import { handleDataEndpoint } from "./data-endpoint-handler.js";
import { handlePageDataEndpoint } from "./page-data-endpoint-handler.js";
import { handleVirtualModule } from "./virtual-module-handler.js";
import { handleBatchModuleEndpoint } from "./batch-module-handler.js";
import { HTTP_METHOD_NOT_ALLOWED, PRIORITY_MEDIUM } from "../../../../utils/constants/index.js";
import { createErrorResponseFromDefinition, PROJECT_EXECUTION_UNAVAILABLE, } from "../../../../errors/index.js";
import { requiresIsolatedProjectRuntime } from "../../../../security/project-locality.js";
const MODULE_ENDPOINT_PREFIXES = [
    "/_vf_modules/",
    "/_veryfront/modules/",
    "/_veryfront/pages/",
    "/_veryfront/data/",
    "/_veryfront/page-data/",
];
const HOST_RENDERER_ENDPOINT_PREFIXES = [
    "/_veryfront/modules/",
    "/_veryfront/pages/",
    "/_veryfront/data/",
    "/_veryfront/page-data/",
];
export class ModuleHandler extends BaseHandler {
    metadata = {
        name: "ModuleHandler",
        priority: PRIORITY_MEDIUM,
        patterns: MODULE_ENDPOINT_PREFIXES.map((pattern) => ({
            pattern,
            prefix: true,
        })),
    };
    handle(req, ctx) {
        const pathname = new URL(req.url).pathname;
        const { createResponseBuilder, respond, logDebug, getErrorMessage } = this.helpers;
        const proxyOptions = { requireToken: true };
        const method = req.method.toUpperCase();
        const isOwnedPath = MODULE_ENDPOINT_PREFIXES.some((prefix) => pathname.startsWith(prefix));
        if (isOwnedPath &&
            method !== "GET" &&
            method !== "HEAD") {
            return Promise.resolve(respond(new Response("Method not allowed", {
                status: HTTP_METHOD_NOT_ALLOWED,
                headers: {
                    "Allow": "GET, HEAD",
                    "Cache-Control": "no-store",
                    "Content-Type": "text/plain; charset=utf-8",
                },
            })));
        }
        // These endpoints delegate to the legacy renderer, whose module loader
        // imports page and layout code in the host process rather than through a
        // generation-owned prepared module graph.
        //
        // That is a renderer-architecture concern, not a policy one, so it does not
        // decide who may execute tenant code: the host-execution capability does.
        // A host that grants the capability is asserting it is a suitable executor,
        // and this surface honours that like every other. `rsc/endpoints/
        // endpoint-router.ts` already resolved the identical tension the same way.
        if (requiresIsolatedProjectRuntime(ctx) &&
            HOST_RENDERER_ENDPOINT_PREFIXES.some((prefix) => pathname.startsWith(prefix))) {
            const problem = createErrorResponseFromDefinition(PROJECT_EXECUTION_UNAVAILABLE, {
                detail: "Shared runtimes require a dedicated isolated project runtime for module rendering",
                instance: pathname,
            });
            problem.headers.set("Cache-Control", "no-store");
            return Promise.resolve(respond(method === "HEAD"
                ? new Response(null, {
                    status: problem.status,
                    statusText: problem.statusText,
                    headers: problem.headers,
                })
                : problem));
        }
        if (pathname === "/_vf_modules/_batch") {
            return this.withProxyContext(ctx, () => handleBatchModuleEndpoint(req, respond), proxyOptions);
        }
        if (pathname.startsWith("/_vf_modules/")) {
            return this.withProxyContext(ctx, () => handleModuleServer(req, ctx, createResponseBuilder, respond, logDebug, getErrorMessage), proxyOptions);
        }
        if (pathname.startsWith("/_veryfront/modules/")) {
            return this.withProxyContext(ctx, () => handleVirtualModule(req, ctx, createResponseBuilder, respond, getErrorMessage), proxyOptions);
        }
        if (pathname.startsWith("/_veryfront/pages/")) {
            return this.withProxyContext(ctx, () => handlePageModule(req, pathname, ctx, createResponseBuilder, respond, getErrorMessage), proxyOptions);
        }
        if (pathname.startsWith("/_veryfront/data/")) {
            return this.withProxyContext(ctx, () => handleDataEndpoint(req, pathname, ctx, createResponseBuilder, respond, getErrorMessage), proxyOptions);
        }
        if (pathname.startsWith("/_veryfront/page-data/")) {
            return this.withProxyContext(ctx, () => handlePageDataEndpoint(req, pathname, ctx, createResponseBuilder, respond, getErrorMessage), proxyOptions);
        }
        return Promise.resolve(this.continue());
    }
}
